define ipv4_localnet = 192.168.0.0/16 define ipv6_localnet = fe80::/10 define ipv6_globalnet = 2000::/3 define ipv6_mask = ffff:ffff:ffff:ffff::

add set inet filter ipv6_prefixes { type ipv6_addr . ipv6_addr; flags dynamic, timeout; timeout 1d; size 16; }

add chain inet filter prerouting { type filter hook prerouting priority filter; } add rule inet filter prerouting ct state new ip6 daddr $ipv6_globalnet update @ipv6_prefixes { ip6 daddr . (ip6 daddr & $ipv6_mask) }

add chain inet filter is_local add rule inet filter is_local ip daddr $ipv4_localnet ip saddr $ipv4_localnet accept add rule inet filter is_local ip6 daddr $ipv6_localnet ip6 saddr $ipv6_localnet accept add rule inet filter is_local ip6 daddr $ipv6_globalnet ip6 daddr . (ip6 saddr & $ipv6_mask) @ipv6_prefixes accep
